#[tokio::test]
async fn git_set_diff_view_interleaves_deleted_rows() {
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "edit.rs", "alpha\nbeta\ngamma\n");

    let server = spawn_for_test("diff-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "diff-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: ViewOpenResult = send_request::<ViewOpen>(
        &mut ws,
        &ViewOpenParams {
            transient: None,
            path_index: Some(0),
            relative_path: Some("edit.rs".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            view_id: open.view_id,
            cols: 80,
            rows: 24,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;

    // Modify line 0 in the *live buffer only* (never written to disk): insert "X" at its start.
    let _edit: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id: open.buffer_id,
            text: "X".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;

    // Turn the diff view on: the response carries the re-rendered window with the baseline line
    // shown as a phantom "deleted" row above the edited line.
    let on: ViewportWindowResult = send_request::<GitSetDiffView>(
        &mut ws,
        &GitSetDiffViewParams {
            viewport_id: sub.viewport_id,
            enabled: true,
        },
    )
    .await;
    let line0 = on
        .window
        .root
        .lines()
        .into_iter()
        .find(|l| l.logical_line == 0)
        .expect("line 0 in window");
    assert_eq!(line0.baseline_above.len(), 1, "one deleted baseline row");
    assert_eq!(line0.baseline_above[0].text, "alpha");
    assert_eq!(line0.visual_rows[0].segments[0].text, "Xalpha");
    // The edited real line is tinted as Modified.
    assert_eq!(line0.change.marker(), Some(DiffMarker::Modified));

    // Turning it back off clears the phantom rows.
    let off: ViewportWindowResult = send_request::<GitSetDiffView>(
        &mut ws,
        &GitSetDiffViewParams {
            viewport_id: sub.viewport_id,
            enabled: false,
        },
    )
    .await;
    let line0 = off
        .window
        .root
        .lines()
        .into_iter()
        .find(|l| l.logical_line == 0)
        .unwrap();
    // Phantom rows are gone, but the gutter marker persists — it's always-on, independent of the
    // inline diff toggle.
    assert!(line0.baseline_above.is_empty());
    assert_eq!(line0.change.marker(), Some(DiffMarker::Modified));
    assert!(
        line0.change.emphasis().is_empty(),
        "intra-line emphasis is diff-view-only, like the phantom rows"
    );

    drop(server);
}

/// Blame follow (`git/set_blame_follow`): the server watches this client's cursor itself and
/// pushes `git/blame_changed` after the settle window — no per-move client requests. Enabling
/// arms an immediate refresh; cursor moves re-arm through the `set_cursor` chokepoint; settles
/// that resolve to the same `(line, revision)` push nothing (asserted indirectly: the push after
/// a same-line column move plus a line move is the landing line's, exactly once).
#[tokio::test]
async fn blame_follow_pushes_on_enable_and_cursor_moves() {
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "edit.rs", "alpha\nbeta\ngamma\n");

    let server = spawn_for_test("blame-follow-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "blame-follow-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: ViewOpenResult = send_request::<ViewOpen>(
        &mut ws,
        &ViewOpenParams {
            transient: None,
            path_index: Some(0),
            relative_path: Some("edit.rs".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;

    // Enable follow: the armed refresh pushes line 0's blame with no cursor move at all.
    let () = send_request::<GitSetBlameFollow>(
        &mut ws,
        &GitSetBlameFollowParams {
            buffer_id: open.buffer_id,
            enabled: true,
        },
    )
    .await;
    let push =
        expect_notification_within::<GitBlameChanged>(&mut ws, std::time::Duration::from_secs(10))
            .await;
    assert_eq!(push.buffer_id, open.buffer_id);
    assert_eq!(push.line, 0);
    let blame = push.blame.expect("committed line has blame");
    assert_eq!(blame.author, "Test");
    assert!(!blame.is_uncommitted);

    // A same-line column move (no blame change) followed by a line move: exactly one push
    // arrives, for the landing line — the same-line settle was deduped on (line, revision).
    let _: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id: open.buffer_id,
            motion: Motion::Char {
                direction: Direction::Forward,
                count: 2,
            },
            extend_selection: false,
        },
    )
    .await;
    // Wait for the settle to have actually run rather than sleeping past its window: the point of
    // the assertion below is that this move produced *no* push, and that is only exact once the
    // debounced pass it would have come from is known to be finished.
    settled(&server).await;
    let _: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id: open.buffer_id,
            motion: Motion::LogicalLine {
                direction: Direction::Forward,
                count: 1,
                preserve_col: false,
            },
            extend_selection: false,
        },
    )
    .await;
    let push =
        expect_notification_within::<GitBlameChanged>(&mut ws, std::time::Duration::from_secs(10))
            .await;
    assert_eq!(push.line, 1, "the one push is for the landing line");

    drop(server);
}

/// With the diff view on, a modified line carries intra-line emphasis: the changed word on the
/// buffer line (`diff_emphasis`) and its old-side counterpart on the phantom row (`emphasis`).
#[tokio::test]
async fn diff_view_carries_intraline_emphasis_on_modified_pairs() {
    let dir = tempfile::tempdir().unwrap();
    // Commit one content, then rewrite the file on disk: the buffer opens with "total" where
    // HEAD has "count" — a single-word modification on line 0.
    git_commit_file(dir.path(), "edit.rs", "let count = 1;\nsame\n");
    std::fs::write(dir.path().join("edit.rs"), "let total = 1;\nsame\n").unwrap();

    let server = spawn_for_test("intraline-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "intraline-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: ViewOpenResult = send_request::<ViewOpen>(
        &mut ws,
        &ViewOpenParams {
            transient: None,
            path_index: Some(0),
            relative_path: Some("edit.rs".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            view_id: open.view_id,
            cols: 80,
            rows: 24,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: true,
        },
    )
    .await;

    let line0 = sub
        .window
        .root
        .lines()
        .into_iter()
        .find(|l| l.logical_line == 0)
        .expect("line 0 in window");
    // New side: "total" occupies bytes [4, 9) of "let total = 1;".
    assert_eq!(line0.change.marker(), Some(DiffMarker::Modified));
    assert_eq!(
        line0.change.emphasis(),
        vec![EmphasisRange { start: 4, end: 9 }]
    );
    // Old side: "count" at the same offsets within the phantom row's "let count = 1;".
    assert_eq!(line0.baseline_above.len(), 1);
    assert_eq!(line0.baseline_above[0].text, "let count = 1;");
    assert_eq!(
        line0.baseline_above[0].emphasis,
        vec![EmphasisRange { start: 4, end: 9 }]
    );
    // The untouched line 1 carries neither marker nor emphasis.
    let line1 = sub
        .window
        .root
        .lines()
        .into_iter()
        .find(|l| l.logical_line == 1)
        .unwrap();
    assert_eq!(line1.change.marker(), None);
    assert!(line1.change.emphasis().is_empty());

    drop(server);
}

